INSERT INTO `questions` VALUES (1,'两数之和','简单','给定一个整数数组 nums 和一个整数 target，请在数组中找到两个不同位置的元素，使它们的和等于 target，并返回这两个元素的下标。\n\n每组数据保证恰好存在一组有效答案，同一个元素不能重复使用。两个下标的返回顺序不限。\n\n示例 1：\n\n输入：\nnums = [2,7,11,15]\ntarget = 9\n\n输出：\n[0,1]\n\n解释：\nnums[0] + nums[1] = 2 + 7 = 9。\n\n示例 2：\n\n输入：\nnums = [3,2,4]\ntarget = 6\n\n输出：\n[1,2]\n\n提示：\n\nnums 的长度在 2 到 10000 之间。\nnums[i] 和 target 的取值范围在 -1000000000 到 1000000000 之间。','#include <iostream>\n#include <vector>\n#include <unordered_map>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    vector<int> twoSum(vector<int>& nums, int target)\n    {\n        // write code here\n    }\n};','#include <cstdlib>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nstatic void CheckTwoSum(int index, const std::vector<int>& nums, int target,\n                        const std::vector<int>& actual)\n{\n    bool passed = actual.size() == 2 &&\n                  actual[0] >= 0 && actual[1] >= 0 &&\n                  actual[0] < static_cast<int>(nums.size()) &&\n                  actual[1] < static_cast<int>(nums.size()) &&\n                  actual[0] != actual[1] &&\n                  nums[actual[0]] + nums[actual[1]] == target;\n\n    std::cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n              << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n              << \",\\\"actual\\\":\\\"[\";\n\n    for (size_t i = 0; i < actual.size(); ++i)\n    {\n        if (i != 0) std::cerr << \",\";\n        std::cerr << actual[i];\n    }\n\n    std::cerr << \"]\\\",\\\"expected\\\":\\\"two valid indices\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nint main()\n{\n    {\n        std::vector<int> nums = {2, 7, 11, 15};\n        CheckTwoSum(1, nums, 9, Solution().twoSum(nums, 9));\n    }\n    {\n        std::vector<int> nums = {3, 2, 4};\n        CheckTwoSum(2, nums, 6, Solution().twoSum(nums, 6));\n    }\n    {\n        std::vector<int> nums = {3, 3};\n        CheckTwoSum(3, nums, 6, Solution().twoSum(nums, 6));\n    }\n    return 0;\n}',1,131072),(2,'字母异位词分组','中等','给定一个字符串数组 strs，请把由相同字母、相同出现次数组成的字符串分到同一组中。\n\n例如，\"eat\"、\"tea\" 和 \"ate\" 排序后都为 \"aet\"，因此属于同一组。答案中各组以及组内字符串的顺序不限。\n\n示例 1：\n\n输入：\nstrs = [\"eat\",\"tea\",\"tan\",\"ate\",\"nat\",\"bat\"]\n\n输出：\n[[\"bat\"],[\"nat\",\"tan\"],[\"ate\",\"eat\",\"tea\"]]\n\n示例 2：\n\n输入：\nstrs = [\"\"]\n\n输出：\n[[\"\"]]\n\n提示：\n\nstrs 的长度在 1 到 10000 之间。\n每个字符串长度在 0 到 100 之间。\n字符串只包含小写英文字母。','#include <iostream>\n#include <vector>\n#include <string>\n#include <unordered_map>\n#include <algorithm>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    vector<vector<string>> groupAnagrams(vector<string>& strs)\n    {\n        // write code here\n    }\n};','#include <cstdlib>\n#include <sstream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nstatic std::string JsonEscape(const std::string& text)\n{\n    std::string out;\n    for (char ch : text)\n    {\n        switch (ch)\n        {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case \'\"\': out += \"\\\\\\\"\"; break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstatic std::string ToText(const T& value)\n{\n    std::ostringstream out;\n    out << value;\n    return out.str();\n}\n\ntemplate <class T>\nstatic std::string ToText(const std::vector<T>& values)\n{\n    std::string out = \"[\";\n    for (size_t i = 0; i < values.size(); ++i)\n    {\n        if (i != 0) out += \",\";\n        out += ToText(values[i]);\n    }\n    out += \"]\";\n    return out;\n}\n\nstatic std::string ToText(const std::string& value)\n{\n    return value;\n}\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected)\n{\n    bool passed = actual == expected;\n    std::cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n              << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n              << \",\\\"actual\\\":\\\"\" << JsonEscape(ToText(actual))\n              << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(ToText(expected))\n              << \"\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nstatic void NormalizeGroups(std::vector<std::vector<std::string>>& groups)\n{\n    for (auto& group : groups)\n    {\n        std::sort(group.begin(), group.end());\n    }\n    std::sort(groups.begin(), groups.end());\n}\n\nint main()\n{\n    {\n        std::vector<std::string> strs = {\"eat\",\"tea\",\"tan\",\"ate\",\"nat\",\"bat\"};\n        auto actual = Solution().groupAnagrams(strs);\n        std::vector<std::vector<std::string>> expected = {\n            {\"eat\",\"tea\",\"ate\"}, {\"tan\",\"nat\"}, {\"bat\"}\n        };\n        NormalizeGroups(actual);\n        NormalizeGroups(expected);\n        CheckCase(1, actual, expected);\n    }\n    {\n        std::vector<std::string> strs = {\"\"};\n        auto actual = Solution().groupAnagrams(strs);\n        std::vector<std::vector<std::string>> expected = {{\"\"}};\n        NormalizeGroups(actual);\n        NormalizeGroups(expected);\n        CheckCase(2, actual, expected);\n    }\n    return 0;\n}',1,131072),(3,'最长连续序列','中等','给定一个未排序的整数数组 nums，请找出数字连续的最长序列长度。\n\n连续序列不要求这些数字在原数组中相邻。算法应尽量达到 O(n) 时间复杂度。\n\n示例 1：\n\n输入：\nnums = [100,4,200,1,3,2]\n\n输出：\n4\n\n解释：\n最长连续序列为 [1,2,3,4]。\n\n示例 2：\n\n输入：\nnums = [0,3,7,2,5,8,4,6,0,1]\n\n输出：\n9\n\n提示：\n\nnums 的长度在 0 到 100000 之间。\nnums[i] 的取值范围在 -1000000000 到 1000000000 之间。','#include <iostream>\n#include <vector>\n#include <unordered_set>\n#include <algorithm>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    int longestConsecutive(vector<int>& nums)\n    {\n        // write code here\n    }\n};','#include <cstdlib>\n#include <sstream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nstatic std::string JsonEscape(const std::string& text)\n{\n    std::string out;\n    for (char ch : text)\n    {\n        switch (ch)\n        {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case \'\"\': out += \"\\\\\\\"\"; break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstatic std::string ToText(const T& value)\n{\n    std::ostringstream out;\n    out << value;\n    return out.str();\n}\n\ntemplate <class T>\nstatic std::string ToText(const std::vector<T>& values)\n{\n    std::string out = \"[\";\n    for (size_t i = 0; i < values.size(); ++i)\n    {\n        if (i != 0) out += \",\";\n        out += ToText(values[i]);\n    }\n    out += \"]\";\n    return out;\n}\n\nstatic std::string ToText(const std::string& value)\n{\n    return value;\n}\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected)\n{\n    bool passed = actual == expected;\n    std::cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n              << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n              << \",\\\"actual\\\":\\\"\" << JsonEscape(ToText(actual))\n              << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(ToText(expected))\n              << \"\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nint main()\n{\n    {\n        std::vector<int> nums = {100,4,200,1,3,2};\n        CheckCase(1, Solution().longestConsecutive(nums), 4);\n    }\n    {\n        std::vector<int> nums = {0,3,7,2,5,8,4,6,0,1};\n        CheckCase(2, Solution().longestConsecutive(nums), 9);\n    }\n    {\n        std::vector<int> nums;\n        CheckCase(3, Solution().longestConsecutive(nums), 0);\n    }\n    return 0;\n}',1,131072),(4,'移动零','简单','给定一个整数数组 nums，请把所有 0 移动到数组末尾，同时保持所有非零元素原来的相对顺序。\n\n必须直接修改原数组，不能复制出另一个同样大小的数组。\n\n示例 1：\n\n输入：\nnums = [0,1,0,3,12]\n\n输出：\n[1,3,12,0,0]\n\n示例 2：\n\n输入：\nnums = [0]\n\n输出：\n[0]\n\n提示：\n\nnums 的长度在 1 到 10000 之间。\nnums[i] 的取值范围在 -2147483648 到 2147483647 之间。','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    void moveZeroes(vector<int>& nums)\n    {\n        // write code here\n    }\n};','#include <cstdlib>\n#include <sstream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nstatic std::string JsonEscape(const std::string& text)\n{\n    std::string out;\n    for (char ch : text)\n    {\n        switch (ch)\n        {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case \'\"\': out += \"\\\\\\\"\"; break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstatic std::string ToText(const T& value)\n{\n    std::ostringstream out;\n    out << value;\n    return out.str();\n}\n\ntemplate <class T>\nstatic std::string ToText(const std::vector<T>& values)\n{\n    std::string out = \"[\";\n    for (size_t i = 0; i < values.size(); ++i)\n    {\n        if (i != 0) out += \",\";\n        out += ToText(values[i]);\n    }\n    out += \"]\";\n    return out;\n}\n\nstatic std::string ToText(const std::string& value)\n{\n    return value;\n}\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected)\n{\n    bool passed = actual == expected;\n    std::cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n              << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n              << \",\\\"actual\\\":\\\"\" << JsonEscape(ToText(actual))\n              << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(ToText(expected))\n              << \"\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nint main()\n{\n    {\n        std::vector<int> nums = {0,1,0,3,12};\n        Solution().moveZeroes(nums);\n        CheckCase(1, nums, std::vector<int>({1,3,12,0,0}));\n    }\n    {\n        std::vector<int> nums = {0};\n        Solution().moveZeroes(nums);\n        CheckCase(2, nums, std::vector<int>({0}));\n    }\n    {\n        std::vector<int> nums = {1,2,3};\n        Solution().moveZeroes(nums);\n        CheckCase(3, nums, std::vector<int>({1,2,3}));\n    }\n    return 0;\n}',1,131072),(5,'盛最多水的容器','中等','给定一个整数数组 height，其中 height[i] 表示第 i 条竖线的高度。\n\n请选择两条竖线，使它们与 x 轴组成的容器可以装下最多的水，并返回最大水量。容器不能倾斜。\n\n示例 1：\n\n输入：\nheight = [1,8,6,2,5,4,8,3,7]\n\n输出：\n49\n\n解释：\n选择下标 1 和下标 8，宽度为 7，较短高度为 7，所以水量为 49。\n\n示例 2：\n\n输入：\nheight = [1,1]\n\n输出：\n1\n\n提示：\n\nheight 的长度在 2 到 100000 之间。\nheight[i] 的取值范围在 0 到 10000 之间。','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    int maxArea(vector<int>& height)\n    {\n        // write code here\n    }\n};','#include <cstdlib>\n#include <sstream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nstatic std::string JsonEscape(const std::string& text)\n{\n    std::string out;\n    for (char ch : text)\n    {\n        switch (ch)\n        {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case \'\"\': out += \"\\\\\\\"\"; break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstatic std::string ToText(const T& value)\n{\n    std::ostringstream out;\n    out << value;\n    return out.str();\n}\n\ntemplate <class T>\nstatic std::string ToText(const std::vector<T>& values)\n{\n    std::string out = \"[\";\n    for (size_t i = 0; i < values.size(); ++i)\n    {\n        if (i != 0) out += \",\";\n        out += ToText(values[i]);\n    }\n    out += \"]\";\n    return out;\n}\n\nstatic std::string ToText(const std::string& value)\n{\n    return value;\n}\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected)\n{\n    bool passed = actual == expected;\n    std::cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n              << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n              << \",\\\"actual\\\":\\\"\" << JsonEscape(ToText(actual))\n              << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(ToText(expected))\n              << \"\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nint main()\n{\n    {\n        std::vector<int> height = {1,8,6,2,5,4,8,3,7};\n        CheckCase(1, Solution().maxArea(height), 49);\n    }\n    {\n        std::vector<int> height = {1,1};\n        CheckCase(2, Solution().maxArea(height), 1);\n    }\n    return 0;\n}',1,131072),(6,'三数之和','中等','给定一个整数数组 nums，请找出所有互不重复的三元组，使三个不同下标对应的元素之和等于 0。\n\n返回结果不能包含重复三元组，三元组之间以及三元组内部的顺序不限。\n\n示例 1：\n\n输入：\nnums = [-1,0,1,2,-1,-4]\n\n输出：\n[[-1,-1,2],[-1,0,1]]\n\n示例 2：\n\n输入：\nnums = [0,1,1]\n\n输出：\n[]\n\n示例 3：\n\n输入：\nnums = [0,0,0]\n\n输出：\n[[0,0,0]]\n\n提示：\n\nnums 的长度在 3 到 3000 之间。\nnums[i] 的取值范围在 -100000 到 100000 之间。','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    vector<vector<int>> threeSum(vector<int>& nums)\n    {\n        // write code here\n    }\n};','#include <cstdlib>\n#include <sstream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nstatic std::string JsonEscape(const std::string& text)\n{\n    std::string out;\n    for (char ch : text)\n    {\n        switch (ch)\n        {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case \'\"\': out += \"\\\\\\\"\"; break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstatic std::string ToText(const T& value)\n{\n    std::ostringstream out;\n    out << value;\n    return out.str();\n}\n\ntemplate <class T>\nstatic std::string ToText(const std::vector<T>& values)\n{\n    std::string out = \"[\";\n    for (size_t i = 0; i < values.size(); ++i)\n    {\n        if (i != 0) out += \",\";\n        out += ToText(values[i]);\n    }\n    out += \"]\";\n    return out;\n}\n\nstatic std::string ToText(const std::string& value)\n{\n    return value;\n}\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected)\n{\n    bool passed = actual == expected;\n    std::cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n              << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n              << \",\\\"actual\\\":\\\"\" << JsonEscape(ToText(actual))\n              << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(ToText(expected))\n              << \"\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nstatic void NormalizeTriples(std::vector<std::vector<int>>& values)\n{\n    for (auto& value : values)\n    {\n        std::sort(value.begin(), value.end());\n    }\n    std::sort(values.begin(), values.end());\n}\n\nint main()\n{\n    {\n        std::vector<int> nums = {-1,0,1,2,-1,-4};\n        auto actual = Solution().threeSum(nums);\n        std::vector<std::vector<int>> expected = {{-1,-1,2},{-1,0,1}};\n        NormalizeTriples(actual);\n        NormalizeTriples(expected);\n        CheckCase(1, actual, expected);\n    }\n    {\n        std::vector<int> nums = {0,1,1};\n        auto actual = Solution().threeSum(nums);\n        std::vector<std::vector<int>> expected;\n        NormalizeTriples(actual);\n        CheckCase(2, actual, expected);\n    }\n    {\n        std::vector<int> nums = {0,0,0};\n        auto actual = Solution().threeSum(nums);\n        std::vector<std::vector<int>> expected = {{0,0,0}};\n        NormalizeTriples(actual);\n        NormalizeTriples(expected);\n        CheckCase(3, actual, expected);\n    }\n    return 0;\n}',1,131072),(7,'接雨水','困难','给定 n 个非负整数，每个整数表示宽度为 1 的柱子高度。请计算下雨后这些柱子之间最多能够接住多少单位的雨水。\n\n示例 1：\n\n输入：\nheight = [0,1,0,2,1,0,1,3,2,1,2,1]