Escape(ToText(expected))\n              << \"\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nint main()\n{\n    CheckCase(1, Solution().minWindow(\"ADOBECODEBANC\", \"ABC\"),\n              std::string(\"BANC\"));\n    CheckCase(2, Solution().minWindow(\"a\", \"a\"),\n              std::string(\"a\"));\n    CheckCase(3, Solution().minWindow(\"a\", \"aa\"),\n              std::string(\"\"));\n    return 0;\n}',1,131072),(13,'最大子数组和','中等','给定一个整数数组 nums，请找出和最大的连续非空子数组，并返回该子数组的元素之和。\n\n示例 1：\n\n输入：\nnums = [-2,1,-3,4,-1,2,1,-5,4]\n\n输出：\n6\n\n解释：\n连续子数组 [4,-1,2,1] 的和最大，为 6。\n\n示例 2：\n\n输入：\nnums = [1]\n\n输出：\n1\n\n示例 3：\n\n输入：\nnums = [5,4,-1,7,8]\n\n输出：\n23\n\n提示：\n\nnums 的长度在 1 到 100000 之间。\nnums[i] 的取值范围在 -10000 到 10000 之间。','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    int maxSubArray(vector<int>& nums)\n    {\n        // write code here\n    }\n};','#include <cstdlib>\n#include <sstream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nstatic std::string JsonEscape(const std::string& text)\n{\n    std::string out;\n    for (char ch : text)\n    {\n        switch (ch)\n        {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case \'\"\': out += \"\\\\\\\"\"; break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstatic std::string ToText(const T& value)\n{\n    std::ostringstream out;\n    out << value;\n    return out.str();\n}\n\ntemplate <class T>\nstatic std::string ToText(const std::vector<T>& values)\n{\n    std::string out = \"[\";\n    for (size_t i = 0; i < values.size(); ++i)\n    {\n        if (i != 0) out += \",\";\n        out += ToText(values[i]);\n    }\n    out += \"]\";\n    return out;\n}\n\nstatic std::string ToText(const std::string& value)\n{\n    return value;\n}\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected)\n{\n    bool passed = actual == expected;\n    std::cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n              << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n              << \",\\\"actual\\\":\\\"\" << JsonEscape(ToText(actual))\n              << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(ToText(expected))\n              << \"\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nint main()\n{\n    {\n        std::vector<int> nums = {-2,1,-3,4,-1,2,1,-5,4};\n        CheckCase(1, Solution().maxSubArray(nums), 6);\n    }\n    {\n        std::vector<int> nums = {1};\n        CheckCase(2, Solution().maxSubArray(nums), 1);\n    }\n    {\n        std::vector<int> nums = {5,4,-1,7,8};\n        CheckCase(3, Solution().maxSubArray(nums), 23);\n    }\n    return 0;\n}',1,131072),(14,'合并区间','中等','给定若干区间 intervals，其中 intervals[i] = [start,end]。\n\n请合并所有相互重叠的区间，并返回合并后的互不重叠区间。\n\n示例 1：\n\n输入：\nintervals = [[1,3],[2,6],[8,10],[15,18]]\n\n输出：\n[[1,6],[8,10],[15,18]]\n\n示例 2：\n\n输入：\nintervals = [[1,4],[4,5]]\n\n输出：\n[[1,5]]\n\n提示：\n\nintervals 的长度在 1 到 10000 之间。\n每个区间都满足 0 <= start <= end <= 10000。','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    vector<vector<int>> merge(vector<vector<int>>& intervals)\n    {\n        // write code here\n    }\n};','#include <cstdlib>\n#include <sstream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nstatic std::string JsonEscape(const std::string& text)\n{\n    std::string out;\n    for (char ch : text)\n    {\n        switch (ch)\n        {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case \'\"\': out += \"\\\\\\\"\"; break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstatic std::string ToText(const T& value)\n{\n    std::ostringstream out;\n    out << value;\n    return out.str();\n}\n\ntemplate <class T>\nstatic std::string ToText(const std::vector<T>& values)\n{\n    std::string out = \"[\";\n    for (size_t i = 0; i < values.size(); ++i)\n    {\n        if (i != 0) out += \",\";\n        out += ToText(values[i]);\n    }\n    out += \"]\";\n    return out;\n}\n\nstatic std::string ToText(const std::string& value)\n{\n    return value;\n}\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected)\n{\n    bool passed = actual == expected;\n    std::cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n              << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n              << \",\\\"actual\\\":\\\"\" << JsonEscape(ToText(actual))\n              << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(ToText(expected))\n              << \"\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nstatic void NormalizeIntervals(std::vector<std::vector<int>>& values)\n{\n    std::sort(values.begin(), values.end());\n}\n\nint main()\n{\n    {\n        std::vector<std::vector<int>> intervals = {{1,3},{2,6},{8,10},{15,18}};\n        auto actual = Solution().merge(intervals);\n        std::vector<std::vector<int>> expected = {{1,6},{8,10},{15,18}};\n        NormalizeIntervals(actual);\n        NormalizeIntervals(expected);\n        CheckCase(1, actual, expected);\n    }\n    {\n        std::vector<std::vector<int>> intervals = {{1,4},{4,5}};\n        auto actual = Solution().merge(intervals);\n        std::vector<std::vector<int>> expected = {{1,5}};\n        NormalizeIntervals(actual);\n        CheckCase(2, actual, expected);\n    }\n    return 0;\n}',1,131072),(15,'轮转数组','中等','给定一个整数数组 nums，请把数组中的元素向右轮转 k 个位置。\n\n当 k 大于数组长度时，实际轮转位置等于 k 对数组长度取余后的结果。\n\n示例 1：\n\n输入：\nnums = [1,2,3,4,5,6,7]\nk = 3\n\n输出：\n[5,6,7,1,2,3,4]\n\n示例 2：\n\n输入：\nnums = [-1,-100,3,99]\nk = 2\n\n输出：\n[3,99,-1,-100]\n\n提示：\n\nnums 的长度在 1 到 100000 之间。\nnums[i] 的取值范围在 -2147483648 到 2147483647 之间。\nk 的取值范围在 0 到 100000 之间。','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    void rotate(vector<int>& nums, int k)\n    {\n        // write code here\n    }\n};','#include <cstdlib>\n#include <sstream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nstatic std::string JsonEscape(const std::string& text)\n{\n    std::string out;\n    for (char ch : text)\n    {\n        switch (ch)\n        {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case \'\"\': out += \"\\\\\\\"\"; break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstatic std::string ToText(const T& value)\n{\n    std::ostringstream out;\n    out << value;\n    return out.str();\n}\n\ntemplate <class T>\nstatic std::string ToText(const std::vector<T>& values)\n{\n    std::string out = \"[\";\n    for (size_t i = 0; i < values.size(); ++i)\n    {\n        if (i != 0) out += \",\";\n        out += ToText(values[i]);\n    }\n    out += \"]\";\n    return out;\n}\n\nstatic std::string ToText(const std::string& value)\n{\n    return value;\n}\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected)\n{\n    bool passed = actual == expected;\n    std::cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n              << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n              << \",\\\"actual\\\":\\\"\" << JsonEscape(ToText(actual))\n              << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(ToText(expected))\n              << \"\\\"}\" << std::endl;\n    if (!passed) std::abort();\n}\n\nint main()\n{\n    {\n        std::vector<int> nums = {1,2,3,4,5,6,7};\n        Solution().rotate(nums, 3);\n        CheckCase(1, nums, std::vector<int>({5,6,7,1,2,3,4}));\n    }\n    {\n        std::vector<int> nums = {-1,-100,3,99};\n        Solution().rotate(nums, 2);\n        CheckCase(2, nums, std::vector<int>({3,99,-1,-100}));\n    }\n    {\n        std::vector<int> nums = {1,2};\n        Solution().rotate(nums, 3);\n        CheckCase(3, nums, std::vector<int>({2,1}));\n    }\n    return 0;\n}',1,131072);
