INSERT INTO `questions_backup_before_hot100` VALUES (1,'两数之和','简单','题目描述\n给定一个整数数组 nums 和一个整数 target，请在数组中找到两个不同位置的元素，使它们的和等于 target，并返回这两个元素的下标。\n\n每组数据保证恰好存在一组有效答案，同一个元素不能重复使用。两个下标的返回顺序不限。\n\n函数要求\nvector<int> twoSum(vector<int>& nums, int target)\n\n输入示例 1\nnums = [2, 7, 11, 15], target = 9\n\n输出示例 1\n[0, 1]\n\n示例说明\nnums[0] + nums[1] = 2 + 7 = 9。\n\n输入示例 2\nnums = [3, 2, 4], target = 6\n\n输出示例 2\n[1, 2]\n\n数据范围\n2 <= nums.size() <= 10000\n-1000000000 <= nums[i] <= 1000000000\n-1000000000 <= target <= 1000000000\n\n资源限制\nCPU 时间：1 秒\n内存限制：128 MB（131072 KB）','#include <iostream>\n#include <vector>\n#include <unordered_map>\nusing namespace std;\n\nclass Solution\n{\npublic:\n    vector<int> twoSum(vector<int>& nums, int target)\n    {\n        // write code here\n    }\n};','#ifndef COMPILER_ONLINE\n#include \"header.cpp\"\n#endif\n#include <algorithm>\n#include <cstdlib>\n#include <sstream>\n#include <string>\n\nstatic string JsonEscape(const string& text)\n{\n    string out;\n    for (size_t i = 0; i < text.size(); ++i)\n    {\n        char ch = text[i];\n        switch (ch)\n        {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case \'\"\': out += \"\\\\\"\"; break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstruct TextFormatter\n{\n    static string Get(const T& value)\n    {\n        ostringstream out;\n        out << value;\n        return out.str();\n    }\n};\n\ntemplate <>\nstruct TextFormatter<string>\n{\n    static string Get(const string& value)\n    {\n        return string(\"\\\"\") + JsonEscape(value) + \"\\\"\";\n    }\n};\n\ntemplate <class T>\nstruct TextFormatter<vector<T>>\n{\n    static string Get(const vector<T>& values)\n    {\n        string out = \"[\";\n        for (size_t i = 0; i < values.size(); ++i)\n        {\n            if (i != 0) out += \",\";\n            out += TextFormatter<T>::Get(values[i]);\n        }\n        out += \"]\";\n        return out;\n    }\n};\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected)\n{\n    bool passed = actual == expected;\n    cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n         << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n         << \",\\\"actual\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(actual))\n         << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(expected))\n         << \"\\\"}\" << endl;\n\n    if (!passed)\n    {\n        abort();\n    }\n}\n\nint main()\n{\n    {\n        vector<int> nums = {2, 7, 11, 15};\n        vector<int> actual = Solution().twoSum(nums, 9);\n        vector<int> expected = {0, 1};\n        sort(actual.begin(), actual.end());\n        CheckCase(1, actual, expected);\n    }\n    {\n        vector<int> nums = {3, 2, 4};\n        vector<int> actual = Solution().twoSum(nums, 6);\n        vector<int> expected = {1, 2};\n        sort(actual.begin(), actual.end());\n        CheckCase(2, actual, expected);\n    }\n    {\n        vector<int> nums = {-3, 4, 3, 90};\n        vector<int> actual = Solution().twoSum(nums, 0);\n        vector<int> expected = {0, 2};\n        sort(actual.begin(), actual.end());\n        CheckCase(3, actual, expected);\n    }\n    return 0;\n}',1,131072),(2,'两数相加','中等','给你两个非空链表，分别表示两个非负整数。\n\n每个链表中的数字按照逆序存储，每个结点只保存一位数字。请将两个数相加，并以相同的链表形式返回计算结果。\n\n除了数字 0 以外，输入的数字不会包含前导零。\n\n示例 1：\n\n输入：\nl1 = [2,4,3]\nl2 = [5,6,4]\n\n输出：\n[7,0,8]\n\n解释：\n链表 [2,4,3] 表示数字 342。\n链表 [5,6,4] 表示数字 465。\n342 + 465 = 807，因此返回 [7,0,8]。\n\n示例 2：\n\n输入：\nl1 = [0]\nl2 = [0]\n\n输出：\n[0]\n\n示例 3：\n\n输入：\nl1 = [9,9,9,9,9,9,9]\nl2 = [9,9,9,9]\n\n输出：\n[8,9,9,9,0,0,0,1]\n\n提示：\n\n每个链表中的结点数量在 1 到 100 之间。\n每个结点的值在 0 到 9 之间。\n输入链表表示的数字不包含前导零，数字 0 除外。','#include <iostream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode *next;\n    ListNode() : val(0), next(nullptr) {}\n    ListNode(int x) : val(x), next(nullptr) {}\n    ListNode(int x, ListNode *next) : val(x), next(next) {}\n};\n\nclass Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        // write code here\n    }\n};','#ifndef COMPILER_ONLINE\n#include \"header.cpp\"\n#endif\n#include <vector>\n#include <cstdlib>\n#include <sstream>\n#include <string>\n\nstatic string JsonEscape(const string& text) {\n    string out;\n    for (size_t i = 0; i < text.size(); ++i) {\n        char ch = text[i];\n        switch (ch) {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case 34: out += char(92); out += char(34); break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\nstatic ListNode* CreateList(const vector<int>& nums) {\n    ListNode dummy(0);\n    ListNode* tail = &dummy;\n    for (size_t i = 0; i < nums.size(); ++i) {\n        tail->next = new ListNode(nums[i]);\n        tail = tail->next;\n    }\n    return dummy.next;\n}\n\nstatic vector<int> ListToVector(ListNode* head) {\n    vector<int> out;\n    while (head) {\n        out.push_back(head->val);\n        head = head->next;\n    }\n    return out;\n}\n\nstatic void FreeList(ListNode* head) {\n    while (head) {\n        ListNode* next = head->next;\n        delete head;\n        head = next;\n    }\n}\n\ntemplate <class T>\nstruct TextFormatter {\n    static string Get(const T& value) {\n        ostringstream out;\n        out << value;\n        return out.str();\n    }\n};\n\ntemplate <class T>\nstruct TextFormatter<vector<T>> {\n    static string Get(const vector<T>& values) {\n        string out = \"[\";\n        for (size_t i = 0; i < values.size(); ++i) {\n            if (i != 0) out += \",\";\n            out += TextFormatter<T>::Get(values[i]);\n        }\n        out += \"]\";\n        return out;\n    }\n};\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected) {\n    bool passed = actual == expected;\n    cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n         << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n         << \",\\\"actual\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(actual))\n         << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(expected))\n         << \"\\\"}\" << endl;\n    if (!passed) abort();\n}\n\nint main() {\n    {\n        ListNode* l1 = CreateList({2, 4, 3});\n        ListNode* l2 = CreateList({5, 6, 4});\n        ListNode* res = Solution().addTwoNumbers(l1, l2);\n        CheckCase(1, ListToVector(res), vector<int>{7, 0, 8});\n        FreeList(l1); FreeList(l2); FreeList(res);\n    }\n    {\n        ListNode* l1 = CreateList({0});\n        ListNode* l2 = CreateList({0});\n        ListNode* res = Solution().addTwoNumbers(l1, l2);\n        CheckCase(2, ListToVector(res), vector<int>{0});\n        FreeList(l1); FreeList(l2); FreeList(res);\n    }\n    {\n        ListNode* l1 = CreateList({9,9,9,9,9,9,9});\n        ListNode* l2 = CreateList({9,9,9,9});\n        ListNode* res = Solution().addTwoNumbers(l1, l2);\n        CheckCase(3, ListToVector(res), vector<int>{8,9,9,9,0,0,0,1});\n        FreeList(l1); FreeList(l2); FreeList(res);\n    }\n    return 0;\n}',1,131072),(3,'无重复字符的最长子串','中等','给定一个字符串 s，请你找出其中不包含重复字符的最长连续子串，并返回这个子串的长度。\n\n子串必须是原字符串中连续的一段字符。\n\n示例 1：\n\n输入：\ns = \"abcabcbb\"\n\n输出：\n3\n\n解释：\n最长的不重复子串是 \"abc\"，长度为 3。\n\n示例 2：\n\n输入：\ns = \"bbbbb\"\n\n输出：\n1\n\n解释：\n最长的不重复子串是 \"b\"，长度为 1。\n\n示例 3：\n\n输入：\ns = \"pwwkew\"\n\n输出：\n3\n\n解释：\n最长的不重复子串可以是 \"wke\"，长度为 3。\n\"pwke\" 虽然没有重复字符，但它不是连续子串，因此不能作为答案。\n\n提示：\n\n字符串长度在 0 到 50000 之间。\n字符串可能包含英文字母、数字、符号和空格。','#include <iostream>\n#include <string>\n#include <unordered_set>\nusing namespace std;\n\nclass Solution {\npublic:\n    int lengthOfLongestSubstring(string s) {\n        