ms2 的长度在 0 到 1000 之间。\n两个数组的总长度至少为 1。\n数组中的元素按照非递减顺序排列。','#include <iostream>\n#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {\n        // write code here\n    }\n};','#ifndef COMPILER_ONLINE\n#include \"header.cpp\"\n#endif\n#include <cstdlib>\n#include <cmath>\n#include <sstream>\n#include <string>\n\nstatic string JsonEscape(const string& text) {\n    string out;\n    for (size_t i = 0; i < text.size(); ++i) {\n        char ch = text[i];\n        switch (ch) {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case 34: out += char(92); out += char(34); break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstruct TextFormatter {\n    static string Get(const T& value) {\n        ostringstream out;\n        out << value;\n        return out.str();\n    }\n};\n\nstatic void CheckCaseDouble(int index, double actual, double expected) {\n    bool passed = std::abs(actual - expected) < 1e-5;\n    cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n         << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n         << \",\\\"actual\\\":\\\"\" << JsonEscape(TextFormatter<double>::Get(actual))\n         << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(TextFormatter<double>::Get(expected))\n         << \"\\\"}\" << endl;\n    if (!passed) abort();\n}\n\nint main() {\n    {\n        vector<int> nums1 = {1, 3};\n        vector<int> nums2 = {2};\n        CheckCaseDouble(1, Solution().findMedianSortedArrays(nums1, nums2), 2.0);\n    }\n    {\n        vector<int> nums1 = {1, 2};\n        vector<int> nums2 = {3, 4};\n        CheckCaseDouble(2, Solution().findMedianSortedArrays(nums1, nums2), 2.5);\n    }\n    return 0;\n}',1,131072),(5,'最长回文子串','中等','给你一个字符串 s，请找出 s 中最长的回文子串并返回。\n\n回文字符串是指从左向右读取和从右向左读取结果相同的字符串。\n\n示例 1：\n\n输入：\ns = \"babad\"\n\n输出：\n\"bab\"\n\n解释：\n\"aba\" 也是符合要求的答案。\n\n示例 2：\n\n输入：\ns = \"cbbd\"\n\n输出：\n\"bb\"\n\n示例 3：\n\n输入：\ns = \"a\"\n\n输出：\n\"a\"\n\n提示：\n\n字符串长度在 1 到 1000 之间。\n字符串只包含英文字母和数字。','#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Solution {\npublic:\n    string longestPalindrome(string s) {\n        // write code here\n    }\n};','#ifndef COMPILER_ONLINE\n#include \"header.cpp\"\n#endif\n#include <cstdlib>\n#include <sstream>\n\nstatic string JsonEscape(const string& text) {\n    string out;\n    for (size_t i = 0; i < text.size(); ++i) {\n        char ch = text[i];\n        switch (ch) {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case 34: out += char(92); out += char(34); break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\nstatic bool IsPalindrome(const string& s) {\n    int l = 0, r = (int)s.size() - 1;\n    while (l < r) {\n        if (s[l++] != s[r--]) return false;\n    }\n    return true;\n}\n\ntemplate <class T>\nstruct TextFormatter {\n    static string Get(const T& value) {\n        ostringstream out;\n        out << value;\n        return out.str();\n    }\n};\n\ntemplate <>\nstruct TextFormatter<string> {\n    static string Get(const string& value) {\n        return string(\"\\\"\") + JsonEscape(value) + \"\\\"\";\n    }\n};\n\nstatic void CheckCaseValid(int index, const string& actual, const string& s, size_t expectedLen) {\n    bool passed = (actual.size() == expectedLen) && IsPalindrome(actual) && (s.find(actual) != string::npos);\n    cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n         << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n         << \",\\\"actual\\\":\\\"\" << JsonEscape(TextFormatter<string>::Get(actual))\n         << \"\\\",\\\"expected\\\":\\\"length \" << expectedLen << \" palindrome\\\"\"\n         << \"}\" << endl;\n    if (!passed) abort();\n}\n\nint main() {\n    {\n        string s = \"babad\";\n        CheckCaseValid(1, Solution().longestPalindrome(s), s, 3);\n    }\n    {\n        string s = \"cbbd\";\n        CheckCaseValid(2, Solution().longestPalindrome(s), s, 2);\n    }\n    return 0;\n}',1,131072),(6,'盛最多水的容器','中等','给定一个长度为 n 的整数数组 height。\n\n第 i 个元素表示坐标位置 i 上的一条竖线高度，这条竖线的两个端点分别是 (i,0) 和 (i,height[i])。\n\n请选择其中两条竖线，使它们与 x 轴组成的容器能够容纳最多的水，并返回最大水量。\n\n容器不能倾斜。\n\n示例 1：\n\n输入：\nheight = [1,8,6,2,5,4,8,3,7]\n\n输出：\n49\n\n解释：\n选择下标 1 和下标 8 的两条竖线。\n容器宽度为 7，较短竖线高度为 7。\n容水量为 7 × 7 = 49。\n\n示例 2：\n\n输入：\nheight = [1,1]\n\n输出：\n1\n\n提示：\n\n数组长度在 2 到 100000 之间。\n每个高度在 0 到 10000 之间。','#include <iostream>\n#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    int maxArea(vector<int>& height) {\n        // write code here\n    }\n};','#ifndef COMPILER_ONLINE\n#include \"header.cpp\"\n#endif\n#include <cstdlib>\n#include <sstream>\n#include <string>\n\nstatic string JsonEscape(const string& text) {\n    string out;\n    for (size_t i = 0; i < text.size(); ++i) {\n        char ch = text[i];\n        switch (ch) {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case 34: out += char(92); out += char(34); break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstruct TextFormatter {\n    static string Get(const T& value) {\n        ostringstream out;\n        out << value;\n        return out.str();\n    }\n};\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected) {\n    bool passed = actual == expected;\n    cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n         << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n         << \",\\\"actual\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(actual))\n         << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(expected))\n         << \"\\\"}\" << endl;\n    if (!passed) abort();\n}\n\nint main() {\n    {\n        vector<int> h = {1, 8, 6, 2, 5, 4, 8, 3, 7};\n        CheckCase(1, Solution().maxArea(h), 49);\n    }\n    {\n        vector<int> h = {1, 1};\n        CheckCase(2, Solution().maxArea(h), 1);\n    }\n    return 0;\n}',1,131072),(7,'三数之和','中等','给你一个整数数组 nums，请找出所有满足以下条件的三元组：\n\n三个元素来自三个不同的下标。\n三个元素之和等于 0。\n返回结果中不能包含重复的三元组。\n\n答案中的三元组顺序以及所有三元组之间的排列顺序均不作要求。\n\n示例 1：\n\n输入：\nnums = [-1,0,1,2,-1,-4]\n\n输出：\n[[-1,-1,2],[-1,0,1]]\n\n解释：\n-1 + -1 + 2 = 0。\n-1 + 0 + 1 = 0。\n其他组合不能形成新的、不重复的答案。\n\n示例 2：\n\n输入：\nnums = [0,1,1]\n\n输出：\n[]\n\n解释：\n不存在三个元素的和等于 0。\n\n示例 3：\n\n输入：\nnums = [0,0,0]\n\n输出：\n[[0,0,0]]\n\n提示：\n\n数组长度在 3 到 3000 之间。\n数组中的元素范围为 -100000 到 100000。','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<vector<int>> threeSum(vector<int>& nums) {\n        // write code here\n    }\n};','#ifndef COMPILER_ONLINE\n#include \"header.cpp\"\n#endif\n#include <cstdlib>\n#include <sstream>\n#include <string>\n\nstatic string JsonEscape(const string& text) {\n    string out;\n    for (size_t i = 0; i < text.size(); ++i) {\n        char ch = text[i];\n        switch (ch) {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case 34: out += char(92); out += char(34); break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\ntemplate <class T>\nstruct TextFormatter {\n    static string Get(const T& value) {\n        ostringstream out;\n        out << value;\n        return out.str();\n    }\n};\n\ntemplate <class T>\nstruct TextFormatter<vector<T>> {\n    static string Get(const vector<T>& values) {\n        string out = \"[\";\n        for (size_t i = 0; i < values.size(); ++i) {\n            if (i != 0) out += \",\";\n            out += TextFormatter<T>::Get(values[i]);\n        }\n        out += \"]\";\n        return out;\n    }\n};\n\nstatic void Normalize(vector<vector<int>>& res) {\n    for (auto& vec : res) sort(vec.begin(), vec.end());\n    sort(res.begin(), res.end());\n}\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected) {\n    bool passed = actual == expected;\n    cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n         << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n         << \",\\\"actual\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(actual))\n         << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(expected))\n         << \"\\\"}\" << endl;\n    if (!passed) abort();\n}\n\nint main() {\n    {\n        vector<int> nums = {-1, 0, 1, 2, -1, -4};\n        vector<vector<int>> res = Solution().threeSum(nums);\n        Normalize(res);\n        vector<vector<int>> exp = {{-1, -1, 2}, {-1, 0, 1}};\n        Normalize(exp);\n        CheckCase(1, res, exp);\n    }\n    {\n        vector<int> nums = {0, 1, 1};\n        vector<vector<int>> res = Solution().threeSum(nums);\n        vector<vector<int>> exp = {};\n        CheckCase(2, res, exp);\n    }\n    {\n        vector<int> nums = {0, 0, 0};\n        vector<vector<int>> res = Solution().threeSum(nums);\n        vector<vector<int>> exp = {{0, 0, 0}};\n        CheckCase(3, res, exp);\n    }\n    return 0;\n}',1,131072),(8,'电话号码的字母组合','中等','给定一个只包含数字 2 到 9 的字符串 digits，请返回这些数字在电话按键上能够表示的所有字母组合。\n\n答案可以按照任意顺序返回。\n\n数字与字母的对应关系如下：\n\n2 对应 abc\n3 对应 def\n4 对应 ghi\n5 对应 jkl\n6 对应 mno\n7 对应 pqrs\n8 对应 tuv\n9 对应 wxyz\n\n示例 1：\n\n输入：\ndigits = \"23\"\n\n输出：\n[\"ad\",\"ae\",\"af\",\"bd\",\"be\",\"bf\",\"cd\",\"ce\",\"cf\"]\n\n示例 2：\n\n输入：\ndigits = \"\"\n\n输出：\n[]\n\n示例 3：\n\n输入：\ndigits = \"2\"\n\n输出：\n[\"a\",\"b\",\"c\"]\n\n提示：\n\ndigits 的长度在 0 