}\" << endl;\n    if (!passed) abort();\n}\n\nint main() {\n    {\n        vector<string> res = Solution().letterCombinations(\"23\");\n        sort(res.begin(), res.end());\n        vector<string> exp = {\"ad\",\"ae\",\"af\",\"bd\",\"be\",\"bf\",\"cd\",\"ce\",\"cf\"};\n        sort(exp.begin(), exp.end());\n        CheckCase(1, res, exp);\n    }\n    {\n        vector<string> res = Solution().letterCombinations(\"\");\n        vector<string> exp = {};\n        CheckCase(2, res, exp);\n    }\n    return 0;\n}',1,131072),(9,'删除链表的倒数第 N 个结点','中等','给你一个单链表的头结点 head 和一个整数 n。\n\n请删除链表的倒数第 n 个结点，并返回删除后的链表头结点。\n\n示例 1：\n\n输入：\nhead = [1,2,3,4,5]\nn = 2\n\n输出：\n[1,2,3,5]\n\n解释：\n链表倒数第 2 个结点的值是 4，删除它后得到 [1,2,3,5]。\n\n示例 2：\n\n输入：\nhead = [1]\nn = 1\n\n输出：\n[]\n\n示例 3：\n\n输入：\nhead = [1,2]\nn = 1\n\n输出：\n[1]\n\n提示：\n\n链表中的结点数量在 1 到 30 之间。\n结点值在 0 到 100 之间。\nn 的范围在 1 到链表结点总数之间。','#include <iostream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode *next;\n    ListNode() : val(0), next(nullptr) {}\n    ListNode(int x) : val(x), next(nullptr) {}\n    ListNode(int x, ListNode *next) : val(x), next(next) {}\n};\n\nclass Solution {\npublic:\n    ListNode* removeNthFromEnd(ListNode* head, int n) {\n        // write code here\n    }\n};','#ifndef COMPILER_ONLINE\n#include \"header.cpp\"\n#endif\n#include <vector>\n#include <cstdlib>\n#include <sstream>\n#include <string>\n\nstatic string JsonEscape(const string& text) {\n    string out;\n    for (size_t i = 0; i < text.size(); ++i) {\n        char ch = text[i];\n        switch (ch) {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case 34: out += char(92); out += char(34); break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\nstatic ListNode* CreateList(const vector<int>& nums) {\n    ListNode dummy(0);\n    ListNode* tail = &du