ng> exp = {\"((()))\",\"(()())\",\"(())()\",\"()(())\",\"()()()\"};\n        sort(exp.begin(), exp.end());\n        CheckCase(1, res, exp);\n    }\n    {\n        vector<string> res = Solution().generateParenthesis(1);\n        vector<string> exp = {\"()\"};\n        CheckCase(2, res, exp);\n    }\n    return 0;\n}',1,131072),(13,'合并 K 个升序链表','困难','给你一个链表数组 lists，其中每个链表都已经按照升序排列。\n\n请将所有链表合并为一个升序链表，并返回合并后链表的头结点。\n\n示例 1：\n\n输入：\nlists = [[1,4,5],[1,3,4],[2,6]]\n\n输出：\n[1,1,2,3,4,4,5,6]\n\n解释：\n三个链表分别为：\n\n1 → 4 → 5\n1 → 3 → 4\n2 → 6\n\n合并后得到：\n\n1 → 1 → 2 → 3 → 4 → 4 → 5 → 6\n\n示例 2：\n\n输入：\nlists = []\n\n输出：\n[]\n\n示例 3：\n\n输入：\nlists = [[]]\n\n输出：\n[]\n\n提示：\n\nlists 中的链表数量可以为 0。\n所有链表中的结点总数量不超过 10000。\n每个链表都已经按照非递减顺序排列。','#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode *next;\n    ListNode() : val(0), next(nullptr) {}\n    ListNode(int x) : val(x), next(nullptr) {}\n    ListNode(int x, ListNode *next) : val(x), next(next) {}\n};\n\nclass Solution {\npublic:\n    ListNode* mergeKLists(vector<ListNode*>& lists) {\n        // write code here\n    }\n};','#ifndef COMPILER_ONLINE\n#include \"header.cpp\"\n#endif\n#include <cstdlib>\n#include <sstream>\n#include <string>\n\nstatic string JsonEscape(const string& text) {\n    string out;\n    for (size_t i = 0; i < text.size(); ++i) {\n        char ch = text[i];\n        switch (ch) {\n        case \'\\\\\': out += \"\\\\\\\\\"; break;\n        case 34: out += char(92); out += char(34); break;\n        case \'\\n\': out += \"\\\\n\"; break;\n        case \'\\r\': out += \"\\\\r\"; break;\n        case \'\\t\': out += \"\\\\t\"; break;\n        default: out += ch; break;\n        }\n    }\n    return out;\n}\n\nstatic ListNode* CreateList(const vector<int>& nums) {\n    ListNode dummy(0);\n    ListNode* tail = &dummy;\n    for (size_t i = 0; i < nums.size(); ++i) {\n        tail->next = new ListNode(nums[i]);\n        tail = tail->next;\n    }\n    return dummy.next;\n}\n\nstatic vector<int> ListToVector(ListNode* head) {\n    vector<int> out;\n    while (head) {\n        out.push_back(head->val);\n        head = head->next;\n    }\n    return out;\n}\n\nstatic void FreeList(ListNode* head) {\n    while (head) {\n        ListNode* next = head->next;\n        delete head;\n        head = next;\n    }\n}\n\ntemplate <class T>\nstruct TextFormatter {\n    static string Get(const T& value) {\n        ostringstream out;\n        out << value;\n        return out.str();\n    }\n};\n\ntemplate <class T>\nstruct TextFormatter<vector<T>> {\n    static string Get(const vector<T>& values) {\n        string out = \"[\";\n        for (size_t i = 0; i < values.size(); ++i) {\n            if (i != 0) out += \",\";\n            out += TextFormatter<T>::Get(values[i]);\n        }\n        out += \"]\";\n        return out;\n    }\n};\n\ntemplate <class T>\nstatic void CheckCase(int index, const T& actual, const T& expected) {\n    bool passed = actual == expected;\n    cerr << \"__OJ_CASE__{\\\"case\\\":\" << index\n         << \",\\\"passed\\\":\" << (passed ? \"true\" : \"false\")\n         << \",\\\"actual\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(actual))\n         << \"\\\",\\\"expected\\\":\\\"\" << JsonEscape(TextFormatter<T>::Get(expected))\n         << \"\\\"}\" << endl;\n    if (!passed) abort();\n}\n\nint main() {\n    {\n        vector<ListNode*> lists = {\n            CreateList({1,4,5}),\n            CreateList({1,3,4}),\n            CreateList({2,6})\n        };\n        ListNode* res = Solution().mergeKLists(lists);\n        CheckCase(1, ListToVector(res), vector<int>{1,1,2,3,4,4,5,6});\n        FreeList(res);\n    }\n    {\n        vector<ListNode*> lists = {};\n        ListNode* res = Solution().mergeKLists(lists);\n        CheckCase(2, ListToVector(res), vector<int>{});\n        FreeList(res);\n    }\n    return 0;\n}',1,131072),(14,'下一个排列','中等','整数数组的下一个排列，是指按照字典序排列时紧接在当前排列之后的更大排列。\n\n请将给定整数数组修改